enable-gh.ps1:
$ghExe = Join-Path $PSScriptRoot '2.102.0\bin\gh.exe'
if (-not (Test-Path -LiteralPath $ghExe -PathType Leaf)) {
    throw "gh.exe not found: $ghExe"
}

$currentPath = [Environment]::GetEnvironmentVariable('PATH', 'Process')
$alreadyPresent = $false
foreach ($entry in ($currentPath -split ';')) {
    if ($entry -ieq $PSScriptRoot) { $alreadyPresent = $true; break }
}
if (-not $alreadyPresent) {
    if ([string]::IsNullOrEmpty($currentPath)) {
        $newPath = $PSScriptRoot
    } else {
        $newPath = $PSScriptRoot + ';' + $currentPath
    }
    [Environment]::SetEnvironmentVariable('PATH', $newPath, 'Process')
}

Remove-Variable ghExe, currentPath, alreadyPresent, entry, newPath -ErrorAction SilentlyContinue
